function trailingZeroes(n) {
  // Each trailing zero needs one factor 2 and one factor 5, so count both prime factors across 1..n.
  let twos = 0;
  let fives = 0;
  for (let i = 2; i <= n; i++) {
    let x = i;
    while (x % 2 === 0) { twos++; x /= 2; }
    while (x % 5 === 0) { fives++; x /= 5; }
  }
  return Math.min(twos, fives);
}

